from django.contrib.auth import get_user_model
from django.db import models

User = get_user_model()

class Author(models.Model):
    name = models.CharField(max_length=120)

class Post(models.Model):
    author = models.ForeignKey(
        Author,
        on_delete=models.CASCADE,
        related_name="posts",
    )
    title = models.CharField(max_length=200)

class Comment(models.Model):
    post = models.ForeignKey(
        Post,
        on_delete=models.CASCADE,
        related_name="comments",
    )

class Invoice(models.Model):
    customer = models.ForeignKey(
        "Customer",
        on_delete=models.PROTECT,
        related_name="invoices",
    )

class Payment(models.Model):
    invoice = models.ForeignKey(
        Invoice,
        on_delete=models.RESTRICT,
        related_name="payments",
    )

class Ticket(models.Model):
    assignee = models.ForeignKey(
        "auth.User",
        on_delete=models.SET_NULL,
        null=True,
        blank=True,
        related_name="tickets",
    )

def get_sentinel_user():
    return User.objects.get_or_create(username="deleted-user")[0]

class AuditEvent(models.Model):
    actor = models.ForeignKey(
        "auth.User",
        on_delete=models.SET(get_sentinel_user),
        related_name="audit_events",
    )

class FallbackOwner(models.Model):
    name = models.CharField(max_length=80)

class Note(models.Model):
    owner = models.ForeignKey(
        FallbackOwner,
        on_delete=models.SET_DEFAULT,
        default=1,
        related_name="notes",
    )

class LegacyLink(models.Model):
    target = models.ForeignKey(
        "Target",
        on_delete=models.DO_NOTHING,
        db_constraint=False,
    )

class Meta:
    constraints = [
        models.UniqueConstraint(
            fields=["author", "slug"],
            name="unique_post_slug_per_author",
        ),
        models.CheckConstraint(
            condition=models.Q(price__gte=0),
            name="post_price_non_negative",
        ),
    ]

from django.core.exceptions import ValidationError
from django.db import models

class Event(models.Model):
    starts_at = models.DateTimeField()
    ends_at = models.DateTimeField()

    def clean(self):
        super().clean()
        if self.ends_at <= self.starts_at:
            raise ValidationError({"ends_at": "The end must be after the start."})

    def save(self, *args, **kwargs):
        self.full_clean()
        return super().save(*args, **kwargs)

